use mip_codex::mps;
fn main(){let args:Vec<_>=std::env::args().collect();if args.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=match mps::read(&args[1]){Ok(m)=>m,Err(e)=>{println!("{}",serde_json::json!({"error":e.to_string()}));return}};let binary=m.variables.iter().all(|v|v.integer&&v.lower==Some(0.)&&v.upper==Some(1.));let nonnegative=!m.maximize&&m.variables.iter().all(|v|v.objective.is_finite()&&v.objective>=0.);let pure=m.rows.iter().filter(|r|r.lower.is_some_and(|l|l>0.&&l<=1.)&&r.upper.is_none()&&r.coefficients.iter().all(|&(_,a)|a==1.)).count();println!("{}",serde_json::json!({"variables":m.variables.len(),"rows":m.rows.len(),"nnz":m.rows.iter().map(|r|r.coefficients.len()).sum::<usize>(),"binary01":binary,"nonnegative_cost":nonnegative,"pure_cover_rows":pure,"all_pure_cover":pure==m.rows.len()}));}
